def get_diff(name):
    rpath = os.path.join(real_dir, name)
    spath = os.path.join(shadow_dir, name)
    r_lines = open(rpath, 'r', encoding='utf-8', errors='replace').readlines() if os.path.exists(rpath) else []
    s_lines = open(spath, 'r', encoding='utf-8', errors='replace').readlines() if os.path.exists(spath) else []
    d = list(difflib.unified_diff(r_lines, s_lines, fromfile='a/' + rpath.replace(chr(92), '/'), tofile='b/' + rpath.replace(chr(92), '/'), lineterm=''))
    return chr(10).join(d) if d else 'Identical, nothing to promote.'

